 const representative=monitors.reduce((a,b)=>(rank[stateOf(a)]||0)>(rank[stateOf(b)]||0)?a:b),patternNames={idle:'정지 수준',normal:'기준 진동',strong:'강한 진동',intermittent:'간헐 진동',unknown:'판단 보류'},patterns={};
