 function chosenCohort(){const all=learningCohorts(state.sessions||[]).find(c=>c.key===selectedCohort);if(!all)return null;const choice=selectedRuns.get(all.key);return choice?{...all,eligible:all.eligible.filter(s=>choice.has(s.id))}:all;}
 function updatePlan(cohort){const key=autoPlanKey(state,cohort);if(key===planKey&&(!planError||Date.now()<planRetryAt))return;planKey=key;plan=null;planError=null;if(!cohort?.eligible.length||cohort.eligible.length>30){planLoading=false;return;}planLoading=true;api('/ui-api/training-plan',autoTrainingPayload(cohort)).then(result=>{if(key!==planKey)return;plan=result;planLoading=false;renderTraining();}).catch(error=>{if(key!==planKey)return;planError=error;planRetryAt=Date.now()+10000;planLoading=false;renderTraining();});}
 let reviewAuthor="";
 const referenceCache=new Map();
